// Purpose: ROW-001 (REQ-001) — through the check endpoint, every word missing its accent is flagged and
// no correctly spelled dictionary word is, over the dictionary's whole accent population, plus the
// row's own examples (gestion, tecnico) and a control showing the flagging path is reached.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, over dictionary-es
// 4.0.0 pinned by SHA-256) and hand-authored from REQ-001's fail-if examples; no expected value comes
// from the product.
//
// Test argument
// ROW-001 promise: a word missing its accent (gestion for gestión, tecnico for técnico) is flagged and a
//   correctly spelled dictionary word is not (REQ-001 AMENDED arms 1 and 2; A-004 spelling with accents
//   included, A-011 the dictionary is Spanish; A-047/A-050 except ano and anos, which no sample here
//   contains); the flag stands where the word stands (D-020 offsets, word = text.slice(start, end)).
// ROW-001 wrong product: a checker that folds accents before the lookup (or normalises "gestion" to
//   "gestión" because the dictionary holds the accented form) and so lets every accent-stripped word
//   pass — the very error REQ-001 puts "above all"; or one that splits words at accented letters
//   (\w-style tokenising), flagging fragments of correct accented words such as "gesti" and "n".
// ROW-001 given: every lower-case dictionary stem of 7+ letters with an acute accent whose stripped
//   form is no dictionary word (≈5,800 pairs, accentPopulation's exclusions documented there), both
//   forms of each pair, shuffled with a fresh seed and joined by spaces and commas into texts under
//   the 10,000-character limit; when: each text is sent to POST /api/check; then: the flags are
//   exactly the stripped forms, each at its own offsets — every stripped form flagged, no accented
//   dictionary word flagged, no flag anywhere else.
// ROW-001 controls: a fresh consonant non-word between dictionary words is flagged at its offsets
//   (the endpoint answers, in the D-020 shape, and does flag); the population guard (more than 5,000
//   pairs) shows the harmful case is reached in bulk, never a near-empty sample.
// ROW-001 technique: a property over the whole generated population (every pair, every run, in a
//   fresh order and fresh positions), plus the row's named example (gestion/gestión, tecnico/técnico
//   beside the near-miss decoys gestiones and técnicos); the dictionary oracle is the authority
//   REQ-001 names, read independently of the product's checker.
// cases: ROW-001 target=ROW-001-every-accent-stripped-form-flagged-and-no-dictionary-word-over-the-generated-population control=ROW-001-control-a-fresh-non-word-is-flagged-at-its-offsets

import { expect, test } from '@playwright/test';
import {
  accentPopulation,
  asActor,
  byPosition,
  checkText,
  compose,
  fillerWords,
  freshNonWord,
  freshRandom,
  isDictionaryWord,
  placeOf,
  type Placed,
} from './harness';

const MAX_TEXT = 9_000; // below REQ-021's 10,000-character limit, so no text is refused for length

const key = (p: Placed) => `${p.start}:${p.end}:${p.word}`;

test('ROW-001-every-accent-stripped-form-flagged-and-no-dictionary-word-over-the-generated-population', async () => {
  test.setTimeout(600_000);
  asActor('anonymous');
  const rng = freshRandom();
  const population = accentPopulation();
  expect(population.length, 'ROW-001 setup: the accent population is the bulk of the dictionary, never a near-empty sample').toBeGreaterThan(5_000);

  const stripped = new Set(population.map((p) => p.stripped));
  const tokens = rng.shuffle(population.flatMap((p) => [p.word, p.stripped]));

  // Cut the shuffled tokens into texts under MAX_TEXT, each with fresh separators.
  const texts: string[][] = [];
  let current: string[] = [];
  let length = 0;
  for (const t of tokens) {
    if (length + t.length + 2 > MAX_TEXT && current.length) {
      texts.push(current);
      current = [];
      length = 0;
    }
    current.push(t);
    length += t.length + 2;
  }
  if (current.length) texts.push(current);

  const notFlagged: string[] = [];
  const dictionaryWordsFlagged: string[] = [];
  const flagsElsewhere: string[] = [];
  let sent = 0;
  for (const chunk of texts) {
    const separators = chunk.slice(1).map(() => (rng.int(4) === 0 ? ', ' : ' '));
    const { text, placed } = compose(chunk, separators);
    const expected = new Set(placed.filter((p) => stripped.has(p.word)).map(key));
    const correct = new Map(placed.filter((p) => !stripped.has(p.word)).map((p) => [key(p), p.word]));
    const answer = await checkText(text);
    sent += chunk.length;
    const actual = new Set(answer.flagged.map((f) => key(placeOf(f))));
    for (const p of placed) if (expected.has(key(p)) && !actual.has(key(p))) notFlagged.push(p.word);
    for (const f of answer.flagged) {
      const k = key(placeOf(f));
      if (expected.has(k)) continue;
      if (correct.has(k)) dictionaryWordsFlagged.push(f.word);
      else flagsElsewhere.push(`${JSON.stringify(f.word)} at ${f.start}-${f.end} (text there: ${JSON.stringify(text.slice(f.start, f.end))})`);
    }
  }
  expect(sent, 'ROW-001 setup: every token of the population was sent').toBe(tokens.length);

  const examples = (xs: string[]) => xs.slice(0, 25);
  expect(
    {
      accentStrippedWordsNotFlagged: notFlagged.length,
      dictionaryWordsFlagged: dictionaryWordsFlagged.length,
      flagsNotAtAWordOfTheText: flagsElsewhere.length,
      examples: {
        notFlagged: examples(notFlagged),
        dictionaryWordsFlagged: examples(dictionaryWordsFlagged),
        flagsElsewhere: examples(flagsElsewhere),
      },
    },
    `ROW-001: over ${population.length} dictionary words and their accent-stripped forms (seed ${rng.seed}), every stripped form is flagged at its place and no dictionary word is`,
  ).toEqual({
    accentStrippedWordsNotFlagged: 0,
    dictionaryWordsFlagged: 0,
    flagsNotAtAWordOfTheText: 0,
    examples: { notFlagged: [], dictionaryWordsFlagged: [], flagsElsewhere: [] },
  });
});

test('ROW-001-named-example-gestion-and-tecnico-flagged-gestion-and-tecnico-with-accents-not', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const misspelled = ['gestion', 'tecnico'];
  const correct = ['gestión', 'técnico', 'gestiones', 'técnicos']; // the row's words, plus near-miss decoys
  for (const w of correct) if (!isDictionaryWord(w)) throw new Error(`setup: the dictionary oracle does not hold ${w}`);
  for (const w of misspelled) if (isDictionaryWord(w)) throw new Error(`setup: the dictionary oracle holds ${w}`);

  const fillers = fillerWords();
  const tokens: string[] = [];
  for (const anchor of rng.shuffle([...misspelled, ...correct])) {
    for (let i = rng.int(3); i >= 0; i--) tokens.push(rng.pick(fillers));
    tokens.push(anchor);
  }
  tokens.push(rng.pick(fillers));
  const { text, placed } = compose(tokens);
  const expected = byPosition(placed.filter((p) => misspelled.includes(p.word)));
  expect(expected.length, 'ROW-001 setup: both misspellings stand in the text').toBe(2);

  const answer = await checkText(text);
  expect(
    byPosition(answer.flagged.map(placeOf)),
    `ROW-001: in ${JSON.stringify(text)} exactly gestion and tecnico are flagged, each at its own place`,
  ).toEqual(expected);
});

test('ROW-001-control-a-fresh-non-word-is-flagged-at-its-offsets', async () => {
  asActor('anonymous');
  const rng = freshRandom();
  const fillers = fillerWords();
  const nonWord = freshNonWord(rng);
  const { text, placed } = compose([rng.pick(fillers), rng.pick(fillers), nonWord, rng.pick(fillers)]);
  const answer = await checkText(text);
  expect(
    answer.flagged.map(placeOf),
    `ROW-001 control: the endpoint flags the non-word ${nonWord} where it stands in ${JSON.stringify(text)}`,
  ).toContainEqual(placed[2]);
});
